# Restricted marketing edits; applies at the server, including REST saves.
if frappe.session.user == 'marketing@callusgardencentre.com':
    if doc.is_new():
        frappe.throw('Use the Publish to Website action; creation is not permitted here.')
    old = frappe.get_doc(doc.doctype, doc.name)
    allowed = ['image', 'description', 'item_group']
    for field in frappe.get_meta(doc.doctype).fields:
        key = field.fieldname
        if not key or field.fieldtype in ['Section Break', 'Column Break', 'Tab Break', 'HTML', 'Button', 'Fold', 'Heading']:
            continue
        if key in allowed:
            continue
        before = old.get(key)
        after = doc.get(key)
        if field.fieldtype in ['Table', 'Table MultiSelect']:
            before = [{k: v for k, v in row.as_dict().items() if k not in ['modified', 'modified_by']} for row in (before or [])]
            after = [{k: v for k, v in row.as_dict().items() if k not in ['modified', 'modified_by']} for row in (after or [])]
        if before != after and not (before in [None, ''] and after in [None, '']):
            frappe.throw('Marketing access cannot change: ' + (field.label or key))
    if doc.doctype == 'Item' and doc.item_group != old.item_group:
        if not frappe.db.exists('Item Group', doc.item_group):
            frappe.throw('Select an existing item category.')

if frappe.session.user == 'marketing@callusgardencentre.com':
    if doc.is_new():
        item = frappe.get_doc('Item', doc.item_code)
        item.check_permission('read')
        if item.disabled:
            frappe.throw('Disabled products require administrator review.')
        # Rebuild all protected values from the real Item and schema defaults.
        # Incoming item/display names, stock fields, route and settings are ignored.
        marketing = {}
        for key in ['website_image', 'short_description', 'web_long_description']:
            marketing[key] = doc.get(key)
        for field in frappe.get_meta('Website Item').fields:
            if field.fieldtype in ['Section Break', 'Column Break', 'Tab Break', 'HTML', 'Button', 'Fold', 'Heading']:
                continue
            if field.fieldtype in ['Table', 'Table MultiSelect']:
                doc.set(field.fieldname, [])
            else:
                doc.set(field.fieldname, field.default if field.default not in [None, ''] else None)
        for key in ['item_code', 'item_name', 'item_group', 'stock_uom', 'brand', 'has_variants', 'variant_of', 'description']:
            doc.set(key, item.get(key))
        doc.web_item_name = item.item_name
        doc.website_warehouse = 'Garden Center - BGL'
        doc.published = 1
        doc.website_image = marketing.get('website_image') or item.image
        doc.short_description = marketing.get('short_description')
        doc.web_long_description = marketing.get('web_long_description')
    if not doc.is_new():
        old = frappe.get_doc(doc.doctype, doc.name)
        allowed = ['website_image', 'short_description', 'web_long_description']
        if doc.published == 1 and not old.published:
            allowed.append('published')
        for field in frappe.get_meta(doc.doctype).fields:
            key = field.fieldname
            if not key or field.fieldtype in ['Section Break', 'Column Break', 'Tab Break', 'HTML', 'Button', 'Fold', 'Heading']:
                continue
            if key in allowed:
                continue
            if key in ['item_group', 'description'] and doc.get(key) == frappe.db.get_value('Item', doc.item_code, key):
                continue
            before = old.get(key)
            after = doc.get(key)
            if field.fieldtype in ['Table', 'Table MultiSelect']:
                before = [{k: v for k, v in row.as_dict().items() if k not in ['modified', 'modified_by']} for row in (before or [])]
                after = [{k: v for k, v in row.as_dict().items() if k not in ['modified', 'modified_by']} for row in (after or [])]
            if before != after and not (before in [None, ''] and after in [None, '']):
                frappe.throw('Marketing access cannot change: ' + (field.label or key))
        if doc.doctype == 'Item' and doc.item_group != old.item_group:
            if not frappe.db.exists('Item Group', doc.item_group):
                frappe.throw('Select an existing item category.')

# Grant read access only after the trusted checkout links its Sales Order.
if doc.sales_order and frappe.db.exists('User', 'marketing@callusgardencentre.com'):
    filters = {'user': 'marketing@callusgardencentre.com', 'allow': 'Sales Order', 'for_value': doc.sales_order, 'apply_to_all_doctypes': 0, 'applicable_for': 'Sales Order'}
    if not frappe.db.exists('User Permission', filters):
        grant = frappe.get_doc(dict(filters, doctype='User Permission'))
        grant.insert(ignore_permissions=True)

frappe.ui.form.on("Item", {
 refresh(frm) {
  if (frappe.session.user !== "marketing@callusgardencentre.com") return;
  const allowed = ["image", "description", "item_group"];
  for (const field of frm.meta.fields) {
   if (!['Section Break','Column Break','Tab Break','HTML','Button'].includes(field.fieldtype))
    frm.set_df_property(field.fieldname, 'read_only', allowed.includes(field.fieldname) ? 0 : 1);
  }
  frm.clear_custom_buttons();
  frm.add_custom_button('Publish to Website', async () => {
   if (frm.is_dirty()) { frappe.msgprint('Please save your changes first.'); return; }
   const result = await frappe.db.get_value('Website Item', {item_code: frm.doc.item_code}, 'name');
   let name = result.message && result.message.name;
   if (name) {
    await frappe.db.set_value('Website Item', name, 'published', 1);
   } else {
    const item = frm.doctype === 'Item' ? frm.doc : (await frappe.db.get_doc('Item', frm.doc.item_code));
    const result = await frappe.call({method:'webshop.webshop.doctype.website_item.website_item.make_website_item', args:{doc:JSON.stringify(item)},freeze:true});
    name = result.message && result.message[0];
   }
   if(name) frappe.set_route('Form','Website Item',name);
  });
 }
});

